function cosmicHome(){const n=next(),name=personalProfile().name;return `<div class="cosmic-home"><div class="home-heading"><div><h1 data-localized="true">${name?esc(ex('greeting',{name})):tr('Bu gün')}</h1><span>${date(placeToday())}</span></div><button class="badge" onclick="go('locations')">⌖ ${esc(placeLabel())}</button></div><button class="cosmic-prayer" onclick="go('prayers')"><span class="orbit-icon">☾</span><span><small>${tr('Növbəti namaz')}</small><strong>${n?tr(names[n.i]):tr('Namaz vaxtları')}</strong><span>${n?n.left:tr(timeError?'İnternet bağlantısını yoxlayın.':'Yüklənir…')}</span></span><b>${n?prayers[n.i]:'—:—'}</b></button><section class="home-carousel-section"><div class="carousel-label"><span>${ux('tools')}</span><span>✦ SHAMS</span></div><div class="home-carousel" data-swipe-lock="true" onscroll="syncHomeSlide(this)" aria-label="${ux('tools')}">${homeGroups.map((g,i)=>`<section class="home-slide" aria-label="${ux(g.title)}"><h2>${ux(g.title)}</h2><div>${g.items.map(([r,icon,title])=>`<button onclick="go('${r}')"><i>${icon}</i><strong>${tr(title)}</strong><span>↗</span></button>`).join('')}</div></section>`).join('')}</div><div class="carousel-controls"><button aria-label="${ux('previous')}" onclick="moveHomeSlide(-1)">‹</button><div>${homeGroups.map((_,i)=>`<button aria-label="${ux('tools')} ${i+1}" aria-pressed="${i===homeSlide}" data-home-dot="${i}" onclick="setHomeSlide(${i})"></button>`).join('')}</div><button aria-label="${ux('next')}" onclick="moveHomeSlide(1)">›</button></div></section>${dailyDuaBanner(false)}<button class="cosmic-pro" onclick="go('pro')"><strong>Shams Pro <i>✦</i></strong><span>$1.99 · ${tr('Reklamsız istifadə')}</span><small>${tr('Tətbiqdən gələn gəlirin 20%-i uşaqlar evinə, ehtiyacı olanlara və sahibsiz heyvanlara yardım üçün ayrılır.')}</small></button></div>`}
function setHomeSlide(n,immediate=false){homeSlide=Math.max(0,Math.min(2,n));const e=document.querySelector('.home-carousel');if(e)e.scrollTo({left:(lang()==='ar'?-1:1)*homeSlide*e.clientWidth,behavior:immediate?'instant':window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelectorAll('[data-home-dot]').forEach((el,i)=>el.setAttribute('aria-pressed',i===homeSlide))}
function moveHomeSlide(n){setHomeSlide(homeSlide+n)}
function syncHomeSlide(el){homeSlide=Math.min(2,Math.round(Math.abs(el.scrollLeft)/Math.max(1,el.clientWidth)));document.querySelectorAll('[data-home-dot]').forEach((e,i)=>e.setAttribute('aria-pressed',i===homeSlide))}
function fastingJournal(){const raw=read('shams-fast-journal',{}),j={};if(raw&&typeof raw==='object'&&!Array.isArray(raw))for(const [date,r]of Object.entries(raw))if(/^\d{4}-\d{2}-\d{2}$/.test(date)&&r&&['fasted','missed'].includes(r.status))j[date]={status:r.status,reason:typeof r.reason==='string'?r.reason:'',note:typeof r.note==='string'?r.note:''};for(const [date,yes]of Object.entries(fasts))if(yes===true&&!j[date]&&/^\d{4}-\d{2}-\d{2}$/.test(date))j[date]={status:'fasted',reason:'',note:''};return j}
let journalMonth=null,fastDraft=null,dayModalFocus=null;
const fastReasons=['travel','illness','period','fatigue','overslept','pregnancy','other'];
function changeJournalMonth(delta){journalMonth=journalMonth||placeToday();journalMonth=new Date(journalMonth.getFullYear(),journalMonth.getMonth()+delta,1,12);render()}
function selectJournalMonth(m,y){journalMonth=new Date(Number(y),Number(m),1,12);render()}
function jumpRamadan(){journalMonth=dateFromKey(ramadanSeason(upcomingRamadanYear()).start);render()}
function monthJournalHTML(){journalMonth=journalMonth||placeToday();const y=journalMonth.getFullYear(),m=journalMonth.getMonth(),first=(new Date(y,m,1).getDay()+6)%7,n=new Date(y,m+1,0).getDate(),today=key(placeToday()),j=fastingJournal(),dates=Array.from({length:n},(_,i)=>key(new Date(y,m,i+1))),good=dates.filter(k=>j[k]?.status==='fasted').length,bad=dates.filter(k=>j[k]?.status==='missed').length,locale=({az:'az-AZ',tr:'tr-TR',ru:'ru-RU',en:'en-GB',ar:'ar'})[lang()],week={az:['B.e','Ç.a','Ç','C.a','C','Ş','B'],tr:['Pt','Sa','Ça','Pe','Cu','Ct','Pz'],ru:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],en:['Mo','Tu','We','Th','Fr','Sa','Su'],ar:['ن','ث','ر','خ','ج','س','ح']}[lang()];return `<section class="card journal-card" data-localized="true"><div class="journal-metrics"><span><b>${good}</b>${ux('monthFasts')}</span><span><b>${bad}</b>${ux('monthMissed')}</span></div><div class="journal-month"><button aria-label="${ux('previous')}" onclick="changeJournalMonth(-1)">‹</button><select aria-label="${ux('month')}" onchange="selectJournalMonth(this.value,${y})">${Array.from({length:12},(_,i)=>`<option value="${i}" ${i===m?'selected':''}>${monthLabel(i)}</option>`).join('')}</select><select aria-label="${ux('year')}" onchange="selectJournalMonth(${m},this.value)">${Array.from({length:Math.max(placeToday().getFullYear()+2,y)-Math.min(2020,y)+1},(_,i)=>Math.min(2020,y)+i).map(v=>`<option ${y===v?'selected':''}>${v}</option>`).join('')}</select><button aria-label="${ux('next')}" onclick="changeJournalMonth(1)">›</button></div><p>${ux('dayHint')}</p><div class="journal-grid">${week.map(v=>`<small>${v}</small>`).join('')}${'<span></span>'.repeat(first)}${dates.map((k,i)=>{const row=j[k],h=hijriParts(dateFromKey(k));return `<button class="${row?.status||''} ${k===today?'today':''} ${h.month===9?'ramadan-date':''}" aria-label="${localizedDate(dateFromKey(k))}${row?' · '+ux(row.status==='fasted'?'fasted':'missed'):''}" ${k>today?'disabled':''} onclick="openFastDay('${k}')"><b>${i+1}</b><i>${row?.status==='fasted'?'✓':row?.status==='missed'?'−':h.month===9?'☾':'·'}</i></button>`}).join('')}</div><button class="textbtn journal-jump" onclick="jumpRamadan()">☾ ${ux('jump')}</button><p class="notice">${ux('private')}</p><div class="journal-history">${dates.filter(k=>j[k]).map(k=>`<button onclick="openFastDay('${k}')"><span class="status-dot ${j[k].status}"></span><strong>${dateFromKey(k).getDate()}</strong><span>${ux(j[k].status==='fasted'?'fasted':'missed')}${j[k].reason?' · '+ux(j[k].reason):''}</span><span>›</span></button>`).join('')}</div></section>`}
function cosmicRamadan(){ensureRamadanTimes();const t=ramadanTimeData?.today;setTimeout(updateRamadanClock,0);return head(rm('ramadan'),'')+personalMessage('ramadanHello')+`<section class="card compact-clock"><div><small>${localizedDate(placeToday())} · ${esc(placeLabel())}</small><p id="ramadanCountdownLabel">${tr('Yüklənir…')}</p><strong id="ramadanCountdown" dir="ltr">— : — : —</strong><span>${rm('sahur')} <b>${t?.fajr||'—:—'}</b> · ${rm('iftar')} <b>${t?.maghrib||'—:—'}</b></span></div><div id="ramadanRing" class="ramadan-ring" style="--ring-progress:0%" aria-hidden="true"><div><span id="ramadanPercent">—</span></div></div></section>${monthJournalHTML()}${ramadanDua()}${ramadanTimeError?`<button class="textbtn" onclick="ensureRamadanTimes(true)">${rm('retry')}</button>`:''}<p class="notice">${rm('moonNote')} ${rm('methodNote')}</p>`}
function openFastDay(date){if(date>key(placeToday()))return;const row=fastingJournal()[date];fastDraft={date,status:row?.status||'',reason:row?.reason||'',note:row?.note||''};dayModalFocus=document.activeElement;paintFastModal()}
function paintFastModal(){let modal=document.querySelector('#fastDayModal');if(!modal){modal=document.createElement('section');modal.id='fastDayModal';modal.className='modal-layer';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');document.body.appendChild(modal);document.querySelector('main').inert=true;document.querySelector('#bottomNav').inert=true}const d=fastDraft;modal.setAttribute('aria-label',localizedDate(dateFromKey(d.date)));modal.innerHTML=`<div class="day-sheet" data-localized="true"><div class="sheet-head"><h2>${localizedDate(dateFromKey(d.date))}</h2><button aria-label="${ux('close')}" onclick="closeFastModal()">×</button></div><div class="fast-status-options"><button class="fasted ${d.status==='fasted'?'chosen':''}" aria-pressed="${d.status==='fasted'}" onclick="draftFastStatus('fasted')">✓ ${ux('fasted')}</button><button class="missed ${d.status==='missed'?'chosen':''}" aria-pressed="${d.status==='missed'}" onclick="draftFastStatus('missed')">− ${ux('missed')}</button></div>${d.status==='missed'?`<h3>${ux('reason')}</h3><div class="reason-options">${fastReasons.map(r=>`<button aria-pressed="${d.reason===r}" onclick="chooseFastReason('${r}')">${ux(r)}</button>`).join('')}</div><label class="field-label">${ux('note')}<textarea maxlength="240" rows="2" oninput="fastDraft.note=this.value">${esc(d.note)}</textarea></label>`:''}<p class="notice">${ux('private')}</p><button class="goldbtn" ${!d.status?'disabled':''} onclick="commitFastDay()">${ux('save')}</button><button class="textbtn" onclick="clearFastDay()">${ux('clear')}</button><p id="fastDayError" class="error" role="status"></p></div>`;modal.querySelector('button')?.focus({preventScroll:true})}
function draftFastStatus(s){fastDraft.status=s;paintFastModal()}
function chooseFastReason(r){fastDraft.reason=r;document.querySelectorAll('.reason-options button').forEach((b,i)=>b.setAttribute('aria-pressed',fastReasons[i]===r))}
function commitFastDay(){if(!fastDraft||!['fasted','missed'].includes(fastDraft.status))return;if(fastDraft.status==='missed'&&!fastReasons.includes(fastDraft.reason)){document.querySelector('#fastDayError').textContent=ux('chooseReason');return}const j=fastingJournal(),d=fastDraft;j[d.date]={status:d.status,reason:d.status==='missed'?d.reason:'',note:d.status==='missed'?String(d.note).trim().slice(0,240):'',updatedAt:new Date().toISOString()};save('shams-fast-journal',j);fasts[d.date]=d.status==='fasted';save('nur-fasts',fasts);closeFastModal();render();toast(ux('saved'))}
function clearFastDay(){if(!fastDraft)return;const j=fastingJournal();delete j[fastDraft.date];delete fasts[fastDraft.date];save('shams-fast-journal',j);save('nur-fasts',fasts);closeFastModal();render()}
function closeFastModal(){document.querySelector('#fastDayModal')?.remove();fastDraft=null;document.querySelector('main').inert=false;document.querySelector('#bottomNav').inert=false;dayModalFocus?.focus?.({preventScroll:true})}
let beadAudio=null;
function playBeadSound(){if(tasbihState().sound===false)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;if(!beadAudio)beadAudio=new C();const play=()=>{const ctx=beadAudio,b=ctx.createBuffer(1,Math.floor(ctx.sampleRate*.045),ctx.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/(ctx.sampleRate*.006));const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=b;filter.type='bandpass';filter.frequency.value=1700;filter.Q.value=.7;gain.gain.value=.25;source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);source.start()};if(beadAudio.state==='suspended')beadAudio.resume().then(play).catch(()=>{});else play()}catch{}}
function setBeadSound(on){const s=tasbihState();s.sound=!!on;save('basira-tasbih',s);if(on)playBeadSound()}
const countBeforeCosmic=countTasbih;countTasbih=function(delta){if(delta>0)playBeadSound();countBeforeCosmic(delta)};
const tasbihBeforeCosmic=tasbihPage;
function cosmicTasbih(){return tasbihBeforeCosmic().replace('<div class="vibration-settings">',`<label class="vibrate-option sound-option"><span>${ux('sound')}</span><input class="switch" type="checkbox" aria-label="${ux('sound')}" ${tasbihState().sound!==false?'checked':''} onchange="setBeadSound(this.checked)"></label><div class="vibration-settings">`)}
function swipeDestination(current,dx,dy,elapsed,rtl=false){const tabs=['home','quran','tasbih','duas','more'],i=tabs.indexOf(tabs.includes(current)?current:({read:'quran',dua:'duas'})[current]||'more');if(i<0||Math.abs(dx)<65||Math.abs(dx)<Math.abs(dy)*1.6||elapsed>750)return null;const n=i+(dx<0?1:-1)*(rtl?-1:1);return tabs[n]||null}
function initializeCosmic(){for(let i=extra.length-1;i>=0;i--)if(extra[i][0]==='fasting')extra.splice(i,1);for(const [r,icon,k]of [['collection','♡','myDuas'],['quiz','✦','quiz'],['asma','☼','names']])if(!extra.some(x=>x[0]===r))extra.push([r,icon,cosmicText[k][0]]);let start=null,suppressUntil=0;document.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.button>0||onboarding||e.target.closest('input,select,textarea,audio,video,[data-swipe-lock],.modal-layer,[role=dialog],.calendar,.journal-grid,.ramadan-days,.beads-area,.tasbih-counter')){start=null;return}if(e.clientX<22||e.clientX>(window.innerWidth||500)-22){start=null;return}start={x:e.clientX,y:e.clientY,time:Date.now(),route}});document.addEventListener('pointerup',e=>{if(window.getSelection?.()?.toString()?.trim()){start=null;return}if(!start)return;const s=start;start=null;const next=swipeDestination(s.route,e.clientX-s.x,e.clientY-s.y,Date.now()-s.time,lang()==='ar');if(next&&route===s.route){suppressUntil=Date.now()+400;go(next)}});document.addEventListener('pointercancel',()=>{start=null});document.addEventListener('click',e=>{if(Date.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation()}},true);document.addEventListener('keydown',e=>{if(!fastDraft)return;if(e.key==='Escape'){e.preventDefault();closeFastModal()}if(e.key==='Tab'){const nodes=[...document.querySelectorAll('#fastDayModal button:not(:disabled),#fastDayModal textarea')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});}
